БЛОК = '\n\n# =========================================================================== #\n# КАЛИБРОВКА 09.11 (владелец: «откалибруем правила… по тем ответам, которые были\n# уже»; «пойдёт, применяй»). Списки фраз расширены по 877 живым ответам, сверка с\n# ручными статусами владельца и разметкой модели: совпадение 60%→75% с моделью,\n# 67%→82% хотя бы с одним. Плюс три предварительных правила: короткий отказ\n# («нет», «нет, спасибо»), «вопрос закрыт / вопросов нет», вопрос в своём тексте\n# без подписи = интерес. Источник и оценка: server/ops/reply_classify_kandidat.py,\n# kalibrovka_otvetov.py --sravnit.\n# =========================================================================== #\nДОБАВКИ = {\n    "_AUTO_REPLY_MARKERS": (\n        \'зарегистрирован\', \'благодарим за обращение\', \'благодарим вас за обращение\',\n        \'в случае заинтересованности\', \'в случае заинтересованности ответственный\',\n        \'обычно мы отвечаем\', \'рады приветствовать вас\', \'ваше обращение\', \'обращение принято\',\n        \'ваше предложение зарегистрировано\', \'направлено на рассмотрение в профильные\',\n        \'почтовый ящик отключен\', \'ящик в скором времени будет заблокирован\',\n        \'изменился основной адрес\', \'адрес электронной почты изменен\', \'переходит на переписку\',\n        \'мой последний рабочий день\', \'закончила работу в компании\', \'закончил работу в компании\',\n        \'на больничном\', \'нахожусь на больничном\', \'в очередном отпуске\', \'буду находиться в отпуске\',\n    ),\n    "_NOT_INTERESTED_MARKERS": (\n        \'потребности нет\', \'потребность отсутствует\', \'нет такой потребности\', \'такой потребности нет\',\n        \'необходимости нет\', \'нет необходимости\', \'необходимости в данном\', \'не нуждаемся\',\n        \'нет задач\', \'таких задач нет\', \'нет таких задач\', \'задача не ставилась\', \'не ставилась задача\',\n        \'не мой профиль\', \'не наш профиль\', \'не по нашему профилю\', \'не наше направление\',\n        \'все имеется\', \'укомплектованы\', \'не используются\', \'не применяем\', \'не применяется\',\n        \'не заинтересовал\', \'не заинтересованы\', \'не подходит\', \'вопрос закрыт\', \'вопрос у нас закрыт\',\n        \'неактуальный\', \'планов нет\', \'планов по замене\', \'не планируется\', \'не планирует\',\n        \'уже предлагали\', \'уже установлен\', \'уже стоит\', \'у нас стоит\', \'у нас есть фотосепаратор\',\n        \'у нас уже есть\', \'уже имеется\', \'имеется фотосепаратор\', \'приостановлена\',\n        \'не пользуемся\', \'не являемся\', \'не являюсь\', \'не является\', \'не переработчик\',\n        \'спасибо, нет\', \'нет, спасибо\', \'нет спасибо\', \'спасибо нет\', \'не требуются\',\n        \'объемы мелкие\', \'объемы малы\', \'слишком малы\', \'не закупаем\', \'нет в планах\',\n        \'добавим ваш контакт\', \'занесу вас в\', \'внесем в базу\', \'в наш реестр\',\n        \'не совсем подходит\', \'не интересени\', \'заменять не собираемся\', \'менять не собираемся\',\n        \'справляемся\', \'мы тоже занимаемся\', \'опрессовываем водой\', \'вопросов нет\',\n        \'не в моей компетенции\', \'не относится к компетенции\', \'нет промышленной линии\',\n    ),\n    "_HOT_MARKERS": (\n        \'просим предоставить кп\', \'предоставьте кп\', \'прошу предоставить кп\', \'направьте кп\',\n        \'пришлите кп\', \'прислать кп\', \'вышлите кп\', \'есть кп\', \'кп?\', \'ткп\',\n        \'пришлите предложение\', \'пришлите ваше предложение\', \'выслать ваше предложение\',\n        \'высылайте\', \'ждем ваших предложений\', \'ждем предложени\', \'ждем опросный\', \'ждем кп\',\n        \'предлагайте\', \'опросный лист\', \'цена вопроса\', \'минимальная цена\', \'с ценами\',\n        \'какая цена\', \'цена?\', \'стоимость?\', \'отправьте ваш телефон\', \'номер телефона для связи\',\n        \'давайте сделаем\', \'подбираем\', \'на пробное\', \'тестирование\', \'прошу прислать\',\n        \'просим прислать\', \'прошу направить\', \'просим направить\', \'прошу предоставить\',\n        \'просим предоставить\',\n    ),\n    "_INTERESTED_MARKERS": (\n        \'интересно\', \'заинтересовал\', \'интересует\', \'интересна\', \'презентаци\', \'буклет\',\n        \'подробную информацию\', \'максимальную информацию\', \'более развернутое\', \'более подробн\',\n        \'как ваше оборудование\', \'кто производитель\', \'стоимост\', \'цена\', \'цену\', \'габарит\',\n        \'производительност\', \'видео\', \'рассмотрим\', \'есть ли у вас\', \'предоставляете ли\',\n        \'можно получить\', \'можно со мной\', \'хотелось бы\', \'вопрос для нас актуал\',\n        \'есть какая то информация\', \'есть какая-то информация\', \'скиньте\',\n    ),\n    "_DEFERRED_MARKERS": (\n        \'в будущем\', \'будем иметь в виду\', \'буду иметь в виду\', \'имеем в виду\',\n        \'чуть позже\', \'когда вернется\', \'вернется из отпуска\', \'через 2 недели\', \'через две недели\',\n        \'позже свяжемся\', \'свяжемся чуть позже\', \'на перспективу\',\n    ),\n    "_UNSUB_MARKERS": (\n        \'удалите из рассылки\', \'уберите мои контакты\', \'удалите мои контакты\', \'где вы взяли мои\',\n        \'удалите наш адрес\', \'исключите из рассылки\',\n    ),\n    "_WRONG_CONTACT_MARKERS": (\n        \'вы перепутали\', \'не имею никакого отношения\', \'не имеем никакого отношения\',\n        \'не имею отношения\', \'вопрос не по адресу\', \'не ко мне\', \'не работаю в данной компании\',\n        \'больше не работаю\', \'давно работаю в другой сфере\',\n    ),\n    "_REDIRECT_MARKERS": (\n        \'отправил ваш запрос\', \'направлена специалисту\', \'передала в службу\', \'перенаправила\',\n        \'в копии коллеги\', \'подключаю\',\n        \'перешлите\', \'направляйте\', \'направьте на\', \'отправить свое предложение в\',\n        \'отправьте на\', \'передано в отдел\', \'передала в\', \'передал в\', \'переслала\', \'переслал\',\n        \'по всем вопросам прошу обращаться\', \'прошу обращаться\', \'обращайтесь, пожалуйста\',\n        \'по адресу\', \'на почту\', \'на адрес\', \'вам лучше написать\', \'лучше писать\',\n    ),\n}\nfor _имя, _доп in ДОБАВКИ.items():\n    _стар = globals()[_имя]\n    globals()[_имя] = tuple(_стар) + tuple(x for x in _доп if x not in _стар)\n\n_базовый = classify_reply\n_КОРОТКИЙ_ОТКАЗ = re.compile(r"^\\W*(?:добрый день|здравствуйте|доброе утро)?\\W*(?:нет|спасибо,?\\s*нет|нет,?\\s*спасибо)\\b[^?]{0,60}$", re.I)\n_ВОПРОС_ЗАКРЫТ = re.compile(r"вопрос\\w*.{0,60}закрыт|вопросов.{0,50}\\bнет\\b", re.I)\n_ПОДПИСЬ = re.compile(r"^\\s*(?:--|с уважением|отправлено из|best regards)", re.I)\n\n\ndef _свой_текст(body):\n    свой = bez_citaty(body)\n    строки = []\n    for с in свой.splitlines():\n        if _ПОДПИСЬ.search(с):\n            break\n        строки.append(с)\n    return "\\n".join(строки).strip() or свой\n\n\ndef classify_reply(subject, body, headers=None):\n    свой = _свой_текст(body)\n    сжатый = re.sub(r"\\s+", " ", свой).strip()\n    if _КОРОТКИЙ_ОТКАЗ.match(сжатый):\n        return ReplySignal(kind=\'not_interested\', confidence=0.9, phone=None,\n                              contact_hint=None, matched=(\'короткий_отказ\',))\n    if _ВОПРОС_ЗАКРЫТ.search(сжатый) and not re.search(r"\\?", сжатый[:300]):\n        return ReplySignal(kind=\'not_interested\', confidence=0.85, phone=None,\n                              contact_hint=None, matched=(\'вопрос_закрыт\',))\n    р = _базовый(subject, свой, headers)\n    # вопрос в СВОЁМ тексте (без подписи) — интерес, если правила ничего другого не нашли\n    if р.kind == \'neutral\' and \'?\' in сжатый[:400]:\n        return ReplySignal(kind=\'interested\', confidence=0.6, phone=р.phone,\n                              contact_hint=р.contact_hint, matched=(\'вопрос_в_своём_тексте\',))\n    return р\n'
т = io.open(ФАЙЛ, encoding="utf-8").read()
if "КАЛИБРОВКА 09.11" in т:
    print("блок уже на месте — ничего не делаю"); raise SystemExit(0)
новый = т.rstrip("\n") + "\n" + БЛОК
print("станет строк: %d (было %d)" % (len(новый.splitlines()), len(т.splitlines())))
if not ПРИМЕНИТЬ:
    print("\n[сухой прогон] применить — с ключом --primenit"); raise SystemExit(0)
запас = "%s.bak-%d" % (ФАЙЛ, int(time.time()))
io.open(запас, "w", encoding="utf-8").write(т)
print("бэкап: %s" % запас)
with io.open(ФАЙЛ, "w", encoding="utf-8") as f:
    f.write(новый)
    f.flush()
    os.fsync(f.fileno())
try:
    py_compile.compile(ФАЙЛ, doraise=True)
    print("py_compile: ок")
except Exception as e:                                        # noqa: BLE001
    io.open(ФАЙЛ, "w", encoding="utf-8").write(т)
    print("КОМПИЛЯЦИЯ УПАЛА, откатил: %s" % str(e)[:200])
    raise SystemExit(1)
print("\n=== ИТОГ ===")
print("правки на месте. Нужен перезапуск службы, чтобы панель их подхватила.")

import subprocess
проба = subprocess.run([sys.executable, "-c", (
    "import sys; sys.path.insert(0, r'C:\\sender'); from sender.reply_classify import classify_reply as c; "
    "[print(repr(t), '->', c('', t).kind) for t in ['Нет, спасибо', 'Добрый день! Потребности нет.', "
    "'Здравствуйте, у вас есть кп? высылайте', 'Ваше предложение зарегистрировано и направлено на рассмотрение', "
    "'Добрый день. Пишите на snab@zavod.ru', 'удалите из рассылки']]")], capture_output=True, text=True, timeout=60)
